#include "meeting_https.h"
#include "esp_http_client.h"
#include "esp_wifi.h"
#include <assert.h>
#include <string.h>
static int done,clock_valid=1,cancelled_flag,init_calls,invalidate_on_headers,cleanup_calls,url_calls,dns_failed;
static const char *expected_authority="example.com";
static int header_timeouts,body_timeouts,cancel_on_timeout,check_alias,open_fails,content_set,sha_set,complete_at_headers,buffered;
static int64_t now_us,open_advance_us;
bool meeting_dns_resolve(const char *host,bool (*cancel)(void *),void *ctx,int64_t deadline,char ip[16]){assert(!strcmp(host,"example.com")&&deadline>now_us&&!cancel(ctx));if(dns_failed)return false;strcpy(ip,"192.0.2.1");return true;}
size_t heap_caps_get_free_size(unsigned caps){(void)caps;return 10000;}
size_t heap_caps_get_largest_free_block(unsigned caps){(void)caps;return 5000;}
int esp_http_client_get_and_clear_last_tls_error(void *h,int *code,int *flags){(void)h;*code=0;*flags=0;return 0;}
int esp_http_client_get_errno(void *h){(void)h;return 0;}
int esp_wifi_sta_get_ap_info(wifi_ap_record_t *ap){ap->rssi=-50;ap->primary=1;return 0;}
int64_t esp_timer_get_time(void){return now_us;}
esp_http_client_handle_t esp_http_client_init(const esp_http_client_config_t *c){assert(c->cert_pem&&!c->skip_cert_common_name_check&&c->disable_auto_redirect&&c->timeout_ms==3000&&!strcmp(c->common_name,"example.com"));assert(strstr(c->url,"https://192.0.2.1")==c->url);init_calls++;return (void*)1;}
int esp_http_client_set_url(void *h,const char *url){(void)h;assert(url);url_calls++;return 0;}
int esp_http_client_delete_header(void *h,const char *key){(void)h;int *v=!strcmp(key,"Content-Type")?&content_set:&sha_set;if(!*v)return ESP_ERR_NOT_FOUND;*v=0;return ESP_OK;}
int esp_http_client_set_method(void *h,esp_http_client_method_t m){(void)h;(void)m;return 0;}
int esp_http_client_set_header(void *h,const char *k,const char *v){(void)h;if(!strcmp(k,"Host"))assert(!strcmp(v,expected_authority));if(!strcmp(k,"Content-Type"))content_set=1;if(!strcmp(k,"X-Content-SHA256"))sha_set=1;return 0;}
int esp_http_client_open(void *h,int n){(void)h;(void)n;done=0;buffered=0;now_us+=open_advance_us;if(open_fails){open_fails=0;return -1;}return 0;}
int esp_http_client_write(void *h,const char *p,int n){(void)h;if(check_alias){assert(n==3&&!memcmp(p,"abc",3));check_alias=0;}return n;}
int64_t esp_http_client_fetch_headers(void *h){(void)h;if(invalidate_on_headers)clock_valid=0;if(complete_at_headers){done=1;buffered=1;}if(header_timeouts){header_timeouts--;now_us+=3000000;if(cancel_on_timeout)cancelled_flag=1;return -ESP_ERR_HTTP_EAGAIN;}return 2;}
int esp_http_client_get_status_code(void *h){(void)h;return 200;}
bool esp_http_client_is_complete_data_received(void *h){(void)h;return done;}
int esp_http_client_read(void *h,char *out,int n){(void)h;if(body_timeouts){body_timeouts--;now_us+=3000000;return -ESP_ERR_HTTP_EAGAIN;}if(done&&!buffered)return 0;if(n<2)return -1;memcpy(out,"{}",2);done=1;buffered=0;return 2;}
int esp_http_client_close(void *h){(void)h;return 0;}
int esp_http_client_cleanup(void *h){(void)h;cleanup_calls++;return 0;}
static bool cancelled(void *c){(void)c;return cancelled_flag;}
static bool time_valid(void *c){(void)c;return clock_valid;}
int main(void){meeting_https_config c={.origin="https://example.com",.device_token="abcdefghijklmnopqrstuvwxyz0123456789",.ca_pem="CA",.is_cancelled=cancelled,.time_valid=time_valid};meeting_upload_transport t;assert(meeting_https_bind(&c,&t));char response[20];size_t n;int status;clock_valid=0;assert(!t.request(t.ctx,"POST","/meeting-service/meetings/x",NULL,NULL,NULL,0,&status,response,sizeof response,&n));assert(init_calls==0);clock_valid=1;assert(t.request(t.ctx,"POST","/meeting-service/meetings/x",NULL,NULL,NULL,0,&status,response,sizeof response,&n));assert(status==200&&n==2);complete_at_headers=1;assert(t.request(t.ctx,"POST","/meeting-service/meetings/x",NULL,NULL,NULL,0,&status,response,sizeof response,&n));assert(n==2&&!memcmp(response,"{}",2));complete_at_headers=0;memcpy(response,"abc",3);check_alias=1;assert(t.request(t.ctx,"PUT","/meeting-service/meetings/x",NULL,NULL,(const uint8_t *)response,3,&status,response,sizeof response,&n));assert(!check_alias&&n==2&&!memcmp(response,"{}",2));assert(init_calls==1&&url_calls==2&&cleanup_calls==0);assert(t.request(t.ctx,"PUT","/meeting-service/meetings/x","application/octet-stream","digest",NULL,0,&status,response,sizeof response,&n));assert(content_set&&sha_set);assert(t.request(t.ctx,"GET","/meeting-service/meetings/x",NULL,NULL,NULL,0,&status,response,sizeof response,&n));assert(!content_set&&!sha_set);int before=cleanup_calls;open_fails=1;assert(!t.request(t.ctx,"GET","/meeting-service/meetings/x",NULL,NULL,NULL,0,&status,response,sizeof response,&n));assert(cleanup_calls==before+1&&c.client==NULL);int initialized=init_calls;assert(t.request(t.ctx,"GET","/meeting-service/meetings/x",NULL,NULL,NULL,0,&status,response,sizeof response,&n));assert(init_calls==initialized+1);open_advance_us=5100000;assert(t.request(t.ctx,"POST","/meeting-service/meetings/x",NULL,NULL,NULL,0,&status,response,sizeof response,&n));open_advance_us=15000000;assert(!t.request(t.ctx,"POST","/meeting-service/meetings/x",NULL,NULL,NULL,0,&status,response,sizeof response,&n));open_advance_us=0;header_timeouts=1;body_timeouts=1;assert(t.request(t.ctx,"POST","/meeting-service/meetings/x",NULL,NULL,NULL,0,&status,response,sizeof response,&n));header_timeouts=5;assert(!t.request(t.ctx,"POST","/meeting-service/meetings/x",NULL,NULL,NULL,0,&status,response,sizeof response,&n));header_timeouts=1;cancel_on_timeout=1;assert(!t.request(t.ctx,"POST","/meeting-service/meetings/x",NULL,NULL,NULL,0,&status,response,sizeof response,&n));cancelled_flag=0;cancel_on_timeout=0;invalidate_on_headers=1;assert(!t.request(t.ctx,"POST","/meeting-service/meetings/x",NULL,NULL,NULL,0,&status,response,sizeof response,&n));assert(t.cancelled(t.ctx));invalidate_on_headers=0;clock_valid=1;cancelled_flag=1;assert(!t.request(t.ctx,"POST","/meeting-service/meetings/x",NULL,NULL,NULL,0,&status,response,sizeof response,&n));meeting_https_close(&c);assert(c.client==NULL);cancelled_flag=0;c.origin="https://example.com:8443";expected_authority="example.com:8443";assert(meeting_https_bind(&c,&t));dns_failed=1;int before_dns=init_calls;assert(!t.request(t.ctx,"GET","/meeting-service/meetings/x",NULL,NULL,NULL,0,&status,response,sizeof response,&n)&&init_calls==before_dns);dns_failed=0;assert(t.request(t.ctx,"GET","/meeting-service/meetings/x",NULL,NULL,NULL,0,&status,response,sizeof response,&n));meeting_https_close(&c);c.origin="http://example.com";assert(!meeting_https_bind(&c,&t));return 0;}
